export type TrackerInstrumentPresetId = 'sine-lead' | 'pulse-lead' | 'triangle-bass' | 'noise-hit' | 'electric-guitar' | 'acoustic-guitar' | 'keyboard' | 'saxophone' | 'violin' | 'kick-drum' | 'snare-drum' | 'hi-hat';

export interface TrackerInstrumentPresetDefinition {
  id: TrackerInstrumentPresetId;
  name: string;
  category: 'lead' | 'bass' | 'percussion';
  loopType: 'none' | 'forward';
  volume: number;
  sampleLength?: number;
  loopStart?: number;
  starterCategory?: 'Duty' | 'Wave' | 'Noise';
  /** Procedural PCM generated by GBA Studio; no external sample/license. */
  provenance: 'gba-studio-procedural-v1';
}

export const TRACKER_INSTRUMENT_PRESETS: TrackerInstrumentPresetDefinition[] = [
  { id: 'pulse-lead', name: 'Pulse Lead', category: 'lead', starterCategory: 'Duty', loopType: 'forward', volume: 56 / 64, provenance: 'gba-studio-procedural-v1' },
  { id: 'sine-lead', name: 'Sine Lead', category: 'lead', starterCategory: 'Wave', loopType: 'forward', volume: 56 / 64, provenance: 'gba-studio-procedural-v1' },
  { id: 'triangle-bass', name: 'Triangle Bass', category: 'bass', starterCategory: 'Wave', loopType: 'forward', volume: 56 / 64, provenance: 'gba-studio-procedural-v1' },
  { id: 'noise-hit', name: 'Noise Hit', category: 'percussion', starterCategory: 'Noise', loopType: 'none', volume: 48 / 64, provenance: 'gba-studio-procedural-v1' },
  { id: 'electric-guitar', name: 'Electric Guitar', category: 'lead', loopType: 'none', sampleLength: 16384, volume: 48 / 64, provenance: 'gba-studio-procedural-v1' },
  { id: 'acoustic-guitar', name: 'Acoustic Guitar', category: 'lead', loopType: 'none', sampleLength: 16384, volume: 52 / 64, provenance: 'gba-studio-procedural-v1' },
  { id: 'keyboard', name: 'Keyboard', category: 'lead', loopType: 'none', sampleLength: 16384, volume: 52 / 64, provenance: 'gba-studio-procedural-v1' },
  { id: 'saxophone', name: 'Saxophone', category: 'lead', loopType: 'forward', loopStart: 64, volume: 48 / 64, provenance: 'gba-studio-procedural-v1' },
  { id: 'violin', name: 'Violin', category: 'lead', loopType: 'forward', loopStart: 1024, volume: 48 / 64, provenance: 'gba-studio-procedural-v1' },
  { id: 'kick-drum', name: 'Drums - Kick', category: 'percussion', starterCategory: 'Noise', loopType: 'none', sampleLength: 4096, volume: 56 / 64, provenance: 'gba-studio-procedural-v1' },
  { id: 'snare-drum', name: 'Drums - Snare', category: 'percussion', starterCategory: 'Noise', loopType: 'none', sampleLength: 4096, volume: 48 / 64, provenance: 'gba-studio-procedural-v1' },
  { id: 'hi-hat', name: 'Drums - Hi-hat', category: 'percussion', starterCategory: 'Noise', loopType: 'none', volume: 40 / 64, provenance: 'gba-studio-procedural-v1' },
];

// A complete 32-frame C4 cycle at this rate follows A4 = 440 Hz. Whole cycles
// keep pulse widths, harmonic intervals and sustain loops exact in sample space.
export const TRACKER_FACTORY_SAMPLE_RATE = Math.round(32 * 440 * 2 ** (-9 / 12));
export const TRACKER_FACTORY_PERIOD = 32;

export type TrackerStarterInstrumentCategory = 'Duty' | 'Wave' | 'Noise';
export interface TrackerStarterInstrumentDefinition { name: string; category: TrackerStarterInstrumentCategory; color: string; pcm: Uint8Array; loop: boolean; loopStart: number; loopEnd: number }

const STARTER_INSTRUMENT_NAMES: Record<TrackerStarterInstrumentCategory, string[]> = {
  Duty: [
    'Fade Out 25% Pulse', 'Fade Out 50% Pulse', 'Fade In 12.5% Pulse', 'Short 12.5% Pulse', 'Short 25% Pulse', 'Short 50% Pulse',
    '12.5% Pulse', '25% Pulse', '50% Pulse', '75% Pulse Custom Vibrato', 'Bass Drum 50% Pulse (Duty 1 Only)',
    'Soft Sweep 50% Pulse (Duty 1 Only)', 'Sweep 12.5% Pulse (Duty 1 Only)', 'Sweep 25% Pulse (Duty 1 Only)',
  ],
  Wave: [
    '12.5% Pulse', '25% Pulse', '31.25% Pulse', '37.5% Pulse', '43.75% Pulse', '50% Pulse', '50% Pulse (Volume 5)',
    '50% Pulse (Volume 3)', '50% Pulse (Volume 1)', 'Square Wave with added Square Wave (2 Octaves higher)',
    'Triangular Wave', 'Triangular with added Square Wave (2 Octaves higher)', 'Saw Wave', 'Distorted Saw Wave',
  ],
  Noise: ['Closed Hi-Hat', 'Closed Hi-Hat 2', 'Closed Hi-Hat 3', 'Open Hi-Hat', 'Crash', 'Crash 2', 'Snare Drum', 'Snare Drum 2', 'Snare Drum 3', 'Metallic Sound', 'Bass Drum', 'Bass Drum 2', 'Explosion', 'Explosion 2'],
};

const STARTER_INSTRUMENT_COLORS = ['#5ce7bd', '#14b5c7', '#65758e', '#40385e', '#198e7b', '#5eb86b', '#9ada56', '#f1e36b', '#ff9458', '#d64b70', '#823d7e', '#cc1b68', '#f27caf', '#efaa97'];

/** Creates the 42 deterministic, C4-tuned GBA-style factory sounds. */
export function createTrackerStarterInstrumentBank(length = 2048, sustainLoops = true): TrackerStarterInstrumentDefinition[] {
  if (!Number.isInteger(length) || length < 64 || length > 65_535) throw new Error('Starter instrument length must be between 64 and 65535 frames.');
  const entries: TrackerStarterInstrumentDefinition[] = [];
  for (const category of ['Duty', 'Wave', 'Noise'] as const) {
    STARTER_INSTRUMENT_NAMES[category].forEach((name, presetIndex) => {
      const pcm = new Uint8Array(length);
      const loopEnd = Math.floor(length / TRACKER_FACTORY_PERIOD) * TRACKER_FACTORY_PERIOD;
      const sustainStart = Math.max(0, loopEnd - 64);
      const animated = category === 'Duty' && (presetIndex <= 2 || presetIndex >= 11);
      const oneShot = category === 'Noise' || (category === 'Duty' && (presetIndex >= 3 && presetIndex <= 5 || presetIndex === 10));
      const widths = category === 'Duty' ? [0.25, 0.5, 0.125, 0.125, 0.25, 0.5, 0.125, 0.25, 0.5, 0.75, 0.5, 0.5, 0.125, 0.25] : [0.125, 0.25, 0.3125, 0.375, 0.4375, 0.5, 0.5, 0.5, 0.5];
      let random = (0x6d2b79f5 ^ (presetIndex + 1) * 0x119de1f3) >>> 0;
      let phase = 0, filteredNoise = 0, previousNoise = 0;
      for (let frame = 0; frame < length; frame += 1) {
        const progress = frame / length;
        const time = frame / TRACKER_FACTORY_SAMPLE_RATE;
        let value: number;
        if (category === 'Noise') {
          random ^= random << 13; random ^= random >>> 17; random ^= random << 5;
          const noise = ((random >>> 0) / 0xffffffff) * 2 - 1;
          const high = (noise - previousNoise) * 0.5;
          previousNoise = noise;
          filteredNoise += (noise - filteredNoise) * 0.12;
          if (presetIndex <= 3) {
            // Closed hats differ in brightness/decay; the open hat rings longer.
            const decay = [90, 65, 45, 14][presetIndex];
            value = (high * 0.75 + noise * [0.08, 0.18, 0.3, 0.25][presetIndex]) * Math.exp(-time * decay);
          } else if (presetIndex <= 5) {
            const metal = Math.sin(time * 2 * Math.PI * 1703) * Math.sin(time * 2 * Math.PI * 2311);
            value = (high * 0.55 + noise * 0.25 + metal * 0.2) * Math.exp(-time * (presetIndex === 4 ? 8 : 5));
          } else if (presetIndex <= 8) {
            const body = Math.sin(time * 2 * Math.PI * [180, 205, 155][presetIndex - 6]);
            value = (noise * 0.68 + body * 0.32) * Math.exp(-time * [23, 17, 12][presetIndex - 6]);
          } else if (presetIndex === 9) {
            value = (Math.sin(time * 2 * Math.PI * 733) * Math.sin(time * 2 * Math.PI * 1171) * 0.8 + high * 0.2) * Math.exp(-time * 10);
          } else if (presetIndex <= 11) {
            phase += ([48, 38][presetIndex - 10] + 130 * Math.exp(-time * 40)) / TRACKER_FACTORY_SAMPLE_RATE;
            value = (Math.sin(phase * 2 * Math.PI) * 0.93 + noise * Math.exp(-time * 100) * 0.07) * Math.exp(-time * (presetIndex === 10 ? 22 : 13));
          } else {
            value = (filteredNoise * 2.2 + noise * 0.12) * (1 - Math.exp(-time * 180)) * Math.exp(-time * (presetIndex === 12 ? 10 : 5));
          }
          value *= Math.min(1, frame / 8) * Math.min(1, (length - 1 - frame) / 64);
        } else {
          const settledFrame = Math.min(frame, sustainStart);
          const envelopeProgress = settledFrame / Math.max(1, length);
          if (category === 'Duty' && presetIndex >= 11) {
            const glide = Math.max(0, 1 - frame / Math.max(1, sustainStart - 64));
            const semitones = presetIndex === 11 ? 3 : presetIndex === 12 ? 12 : -12;
            phase += 2 ** (semitones * glide * glide / 12) / TRACKER_FACTORY_PERIOD;
          } else if (category === 'Duty' && presetIndex === 10) {
            phase += (0.25 + 1.75 * Math.exp(-time * 35)) / TRACKER_FACTORY_PERIOD;
          } else phase = frame / TRACKER_FACTORY_PERIOD;
          const modulated = phase + (category === 'Duty' && presetIndex === 9 ? Math.sin(frame * 2 * Math.PI / 1024) * 0.075 : 0);
          const unit = ((modulated % 1) + 1) % 1;
          let wave: number;
          if (category === 'Wave' && presetIndex === 10) wave = 1 - 4 * Math.abs(unit - 0.5);
          else if (category === 'Wave' && presetIndex === 12) wave = unit * 2 - 1 + 1 / TRACKER_FACTORY_PERIOD;
          else if (category === 'Wave' && presetIndex === 13) wave = Math.tanh((unit * 2 - 1 + 1 / TRACKER_FACTORY_PERIOD) * 2.6);
          else if (category === 'Wave' && (presetIndex === 9 || presetIndex === 11)) {
            const base = presetIndex === 11 ? 1 - 4 * Math.abs(unit - 0.5) : unit < 0.5 ? 1 : -1;
            wave = (base + ((unit * 4) % 1 < 0.5 ? 1 : -1) * 0.24) / 1.24;
          } else {
            const width = widths[presetIndex] ?? 0.5;
            // Zero DC, while retaining the exact named duty cycle.
            wave = (unit < width ? 1 - width : -width) / Math.max(width, 1 - width);
          }
          let envelope = 1;
          if (category === 'Duty' && presetIndex === 0) envelope = Math.max(0.12, 1 - envelopeProgress * 0.75);
          if (category === 'Duty' && presetIndex === 1) envelope = Math.max(0.12, 1 - envelopeProgress * 0.5);
          if (category === 'Duty' && presetIndex === 2) envelope = Math.min(1, envelopeProgress * 8 + 0.12);
          if (category === 'Duty' && presetIndex >= 3 && presetIndex <= 5) envelope = Math.exp(-time * [50, 35, 22][presetIndex - 3]) * Math.min(1, frame / 4) * Math.min(1, (length - 1 - frame) / 32);
          if (category === 'Duty' && presetIndex === 10) envelope = Math.exp(-time * 28) * Math.min(1, (length - 1 - frame) / 32);
          if (category === 'Wave' && presetIndex >= 6 && presetIndex <= 8) envelope = [5 / 15, 3 / 15, 1 / 15][presetIndex - 6];
          value = wave * envelope * (category === 'Wave' ? 0.72 : 0.84);
        }
        pcm[frame] = Math.max(-127, Math.min(127, Math.round(value * 120))) & 0xff;
      }
      entries.push({name, category, color: STARTER_INSTRUMENT_COLORS[presetIndex], pcm, loop: !oneShot,
        loopStart: sustainLoops && animated ? sustainStart : 0, loopEnd: oneShot ? 0 : loopEnd});
    });
  }
  return entries;
}

/** Returns deterministic signed 8-bit mono PCM at the GBA Tracker starter rate. */
export function createTrackerInstrumentPresetPcm(presetId: TrackerInstrumentPresetId, length = TRACKER_INSTRUMENT_PRESETS.find(preset => preset.id === presetId)?.sampleLength ?? 2048): Uint8Array {
  if (!Number.isInteger(length) || length < 1 || length > 65_535) throw new Error('Instrument preset length must be between 1 and 65535 frames.');
  if (!TRACKER_INSTRUMENT_PRESETS.some(preset => preset.id === presetId)) throw new Error(`Unknown tracker instrument preset: ${String(presetId)}`);
  const result = new Uint8Array(length);
  let random = 0x6d2b79f5;
  let drumPhase = 0;
  for (let frame = 0; frame < length; frame += 1) {
    const phase = (frame % TRACKER_FACTORY_PERIOD) / TRACKER_FACTORY_PERIOD;
    let value: number;
    if (presetId === 'sine-lead') value = Math.sin(phase * Math.PI * 2) * 92;
    else if (presetId === 'pulse-lead') value = (phase < 0.375 ? 1 : -0.6) * 76;
    else if (presetId === 'triangle-bass') value = (1 - 4 * Math.abs(phase - 0.5)) * 100;
    else if (presetId === 'noise-hit') {
      random ^= random << 13; random ^= random >>> 17; random ^= random << 5;
      const envelope = Math.max(0, 1 - frame / length);
      value = (((random >>> 0) / 0xffffffff) * 2 - 1) * 104 * envelope;
    } else {
      random ^= random << 13; random ^= random >>> 17; random ^= random << 5;
      const noise = ((random >>> 0) / 0xffffffff) * 2 - 1;
      const time = frame / TRACKER_FACTORY_SAMPLE_RATE;
      const angle = phase * Math.PI * 2;
      const attack = Math.min(1, frame / 24);
      const release = Math.min(1, (length - 1 - frame) / 128);
      if (presetId === 'electric-guitar') {
        const string = Math.sin(angle) + 0.48 * Math.sin(angle * 2) * Math.exp(-time * 4) + 0.25 * Math.sin(angle * 3) * Math.exp(-time * 8);
        value = Math.tanh(string * 2) * Math.exp(-time * 2.8) * attack * release * 100;
      } else if (presetId === 'acoustic-guitar') {
        const string = Math.sin(angle) * Math.exp(-time * 2.5) + 0.5 * Math.sin(angle * 2) * Math.exp(-time * 5) + 0.3 * Math.sin(angle * 3) * Math.exp(-time * 8) + noise * Math.exp(-time * 80) * 0.12;
        value = string * attack * release * 68;
      } else if (presetId === 'keyboard') {
        const body = Math.sin(angle) * Math.exp(-time * 2.4) + 0.42 * Math.sin(angle * 2) * Math.exp(-time * 5) + 0.18 * Math.sin(angle * 4) * Math.exp(-time * 10);
        value = body * attack * release * 75;
      } else if (presetId === 'saxophone') {
        const reed = Math.sin(angle) + 0.45 * Math.sin(angle * 2) + 0.24 * Math.sin(angle * 3) + 0.12 * Math.sin(angle * 4);
        value = Math.tanh(reed * 1.4) * Math.min(1, frame / 64) * 96;
      } else if (presetId === 'violin') {
        const bowed = Math.sin(angle) + 0.42 * Math.sin(angle * 2) + 0.3 * Math.sin(angle * 3)
          + 0.18 * Math.sin(angle * 4) + 0.12 * Math.sin(angle * 5) + 0.08 * Math.sin(angle * 6);
        const bowAttack = (1 - Math.cos(Math.PI * Math.min(1, frame / 768))) / 2;
        value = bowed * bowAttack * 68;
      } else if (presetId === 'kick-drum') {
        drumPhase += 2 * Math.PI * (48 + 150 * Math.exp(-time * 35)) / TRACKER_FACTORY_SAMPLE_RATE;
        value = (Math.sin(drumPhase) * Math.exp(-time * 16) + noise * Math.exp(-time * 150) * 0.12) * attack * release * 110;
      } else if (presetId === 'snare-drum') {
        value = (noise * 0.75 + Math.sin(2 * Math.PI * 180 * time) * 0.25) * Math.exp(-time * 22) * attack * release * 110;
      } else {
        const metal = Math.sin(angle * 11) * Math.sin(angle * 17);
        value = (noise * 0.65 + metal * 0.35) * Math.exp(-time * 45) * attack * release * 85;
      }
    }
    const signed = Math.max(-127, Math.min(127, Math.round(value)));
    result[frame] = signed & 0xff;
  }
  return result;
}
